        'provider' => $provider,
        'status' => 'ok',
        'slug' => $slug,
        'solo_process_id' => $soloProcessId,
        'kind' => $kind,
        'started_at' => $startedAt,
        'marker_match' => 'exact',
        'artifact' => $extract['artifact'] ?? null,
        'source' => $extract['source'] ?? 'lane_close_capture',
    ];

    if (isset($extract['disambiguation_basis'])) {
        $manifest['disambiguation_basis'] = $extract['disambiguation_basis'];
    }

    if (isset($extract['timestamp_corroboration'])) {
        $manifest['timestamp_corroboration'] = $extract['timestamp_corroboration'];
    }

    writeJsonFile($stagingBase.'/manifest.json', $manifest);
    writeJsonFile($stagingBase.'/usage.json', $extract['usage'] ?? []);
    file_put_contents($stagingBase.'/messages.jsonl', ($extract['messages_jsonl'] ?? '')."\n");

    if (!empty($extract['raw_files'])) {
        foreach ($extract['raw_files'] as $rf) {
            $src = $rf['path'];
            $dest = $stagingBase.'/raw/'.$rf['archive_name'];
            if (is_file($src)) {
                copyFileOrFail($src, $dest);
            }
        }
    }

    $result = [
        'status' => 'ok',
        'provider' => $provider,
        'solo_process_id' => $soloProcessId,
        'slug' => $slug,
        'started_at' => $startedAt,
        'staging_dir' => $stagingBase,
    ];
    echo json_encode($result, JSON_UNESCAPED_SLASHES)."\n";
    exit(0);
}

// Failure or unsupported path: write explicit manifest entry (supports waiver later)
$manifest = [
    'schema_version' => 1,
    'provider' => $provider,
    'status' => $extract['status'] ?? 'missing',
    'slug' => $slug,
    'solo_process_id' => $soloProcessId,
    'kind' => $kind,
    'started_at' => $startedAt,
    'reason' => $extract['reason'] ?? 'capture_failed',
    'checked' => $extract['checked'] ?? [],
    'marker' => $markerNeedle,
];
writeJsonFile($stagingBase.'/manifest.json', $manifest);

fwrite(STDERR, "capture failed for solo_process_id={$soloProcessId} provider={$provider}: ".($extract['reason'] ?? 'unknown')."\n");
if (!empty($extract['checked'])) {
    fwrite(STDERR, "candidates checked:\n".json_encode($extract['checked'], JSON_PRETTY_PRINT)."\n");
}
if (($extract['status'] ?? '') === 'ambiguous') {
    fwrite(STDERR, "ambiguous: exact marker \"Solo process ID: {$soloProcessId}\" matched multiple sessions; inspect checked list above.\n");
}
exit(1);

