/**
 * @return list<string>
 */
function tableColumns(PDO $db, string $table): array
{
    $columns = [];
    $stmt = $db->query('PRAGMA table_info('.quoteIdentifier($table).')');

    foreach ($stmt->fetchAll(PDO::FETCH_ASSOC) as $row) {
        if (isset($row['name']) && is_string($row['name'])) {
            $columns[] = $row['name'];
        }
    }

    return $columns;
}

function quoteIdentifier(string $identifier): string
{
    return '"'.str_replace('"', '""', $identifier).'"';
}

function inferProviderFromCommandOrName(string $command, string $name, string $kind): string
{
    $hay = strtolower($command.' '.$name);
    if (str_contains($hay, 'codex') || str_contains($hay, 'openai') || str_contains($hay, 'o1')) {
        return 'codex';
    }
    if (str_contains($hay, 'claude') || str_contains($hay, 'anthropic')) {
        return 'claude';
    }
    if (str_contains($hay, 'grok') || str_contains($hay, 'xai')) {
        return 'grok';
    }
    if ($kind === 'terminal') {
        return 'terminal';
    }
    // default to codex for agent workers in this harness
    return 'codex';
}

function slugify(string $value): string
{
    $slug = strtolower((string) preg_replace('/[^a-zA-Z0-9]+/', '-', $value));
    $slug = trim($slug, '-');
    return $slug === '' ? 'session' : $slug;
}

function ensureDirectory(string $directory): void
{
    if (is_dir($directory)) {
        return;
    }
    if (!mkdir($directory, 0o775, true) && !is_dir($directory)) {
        throw new RuntimeException("Unable to create directory: {$directory}");
    }
}

function writeJsonFile(string $path, array $payload): void
{
    ensureDirectory(dirname($path));
    file_put_contents($path, json_encode($payload, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES | JSON_THROW_ON_ERROR).PHP_EOL);
}

function copyFileOrFail(string $src, string $dest): void
{
    ensureDirectory(dirname($dest));
    if (!copy($src, $dest)) {
        throw new RuntimeException("copy failed: {$src} -> {$dest}");
    }
}

function fileContains(string $path, string $needle): bool
{
    if (!is_file($path)) {
        return false;
    }
    $fh = fopen($path, 'r');
    if ($fh === false) {
        return false;
    }
    while (!feof($fh)) {
        $chunk = fread($fh, 8192);
        if ($chunk !== false && str_contains($chunk, $needle)) {
            fclose($fh);
            return true;
        }
    }
    fclose($fh);
    return false;
}

/** @return list<string> */
function findFiles(string $root, string $glob): array
{
    $files = [];
    if (!is_dir($root)) {
        return $files;
    }
    $it = new RecursiveIteratorIterator(
        new RecursiveDirectoryIterator($root, RecursiveDirectoryIterator::SKIP_DOTS),
        RecursiveIteratorIterator::SELF_FIRST,
    );
    foreach ($it as $entry) {
        if ($entry->isFile() && fnmatch($glob, $entry->getFilename())) {
            $files[] = $entry->getPathname();
        }
    }
    return $files;
}

function captureCodexExact(string $home, string $cwd, int $soloProcessId, string $markerNeedle, mixed $startedAt): array
{
    $root = "{$home}/.codex/sessions";
    $candidates = [];
    $checked = [];
    $rollouts = findFiles($root, '*.jsonl');

    foreach ($rollouts as $file) {
        $checked[] = $file;
        if (! codexFileHasScopedMarker($file, $markerNeedle)) {
            continue;
        }
        $candidates[] = $file;
    }

    if ($candidates === []) {
        return [
            'status' => 'missing',
            'reason' => 'exact_marker_not_found',
            'checked' => array_slice($checked, 0, 20),
        ];
    }

    $chosen = $candidates[0];
    $disambiguationBasis = null;
    $timestampCorroboration = null;

    if (count($candidates) > 1) {
        $normalizedCwd = normalizeCodexCwd($cwd);
        $survivors = [];

        foreach ($candidates as $candidate) {
            $context = codexCandidateContext($candidate);

            if ($context['normalized_cwd'] !== $normalizedCwd) {
                continue;
            }

            if ($context['primary_solo_process_id'] !== $soloProcessId) {
                continue;
            }

            $survivors[] = [
                'path' => $candidate,
                'timestamp' => $context['timestamp'],
            ];
        }

        if (count($survivors) !== 1) {
